<script setup lang="ts">
import {computed,inject,ref} from 'vue';
import {applicationKey} from '../../application';
import {ApiError} from '../../shared/api/client';
const app=inject(applicationKey,null);
const emit=defineEmits<{deleted:[id:string]}>();
const dialog=ref<HTMLDialogElement>(),kind=ref('materials'),context=ref(''),tab=ref('library'),title=ref(''),query=ref(''),sections=ref(['会议概述','关键内容','会议结论','行动项','待解决问题','风险与阻碍']),deleteMeetingId=ref<string|null>(null),deleteRevisionToken=ref<string|null>(null),busy=ref(false),error=ref<string|null>(null);
const names:Record<string,string>={materials:'会议背景材料',library:'从知识库选择背景材料',local:'本地上传背景材料',speaker:'编辑说话人',correction:'转写纠错建议',template:'新增纪要模板',regenerate:'局部重新生成',topic:'新建专题',assign:'归入专题',delete:'删除会议',recordInfo:'会议信息'};
const service=computed(()=>({materials:'背景材料',library:'背景材料知识库',local:'背景材料上传',speaker:'说话人识别与编辑',correction:'转写纠错',template:'自定义模板',regenerate:'局部生成',topic:'专题管理',assign:'专题管理',recordInfo:'录音信息保存'}[kind.value]??'当前')+'服务尚未接入');
function open(next:string,detail='',meetingId:string|null=null,revisionToken:string|null=null){kind.value=next;context.value=detail;title.value='';query.value='';tab.value='library';deleteMeetingId.value=meetingId;deleteRevisionToken.value=revisionToken;busy.value=false;error.value=null;dialog.value?.showModal();}
async function submit(){if(kind.value!=='delete'||!deleteMeetingId.value||!deleteRevisionToken.value||busy.value)return;busy.value=true;error.value=null;try{if(!app?.meetings)throw new Error('meeting service unavailable');await app.meetings.remove(deleteMeetingId.value,deleteRevisionToken.value,new AbortController().signal);const id=deleteMeetingId.value;dialog.value?.close();emit('deleted',id);}catch(cause){error.value=cause instanceof ApiError?cause.message:'删除会议暂未完成，请保留当前页面并重试。';}finally{busy.value=false;}}
defineExpose({open});
</script>
<template><dialog ref="dialog" class="future-panel" :class="{'future-wide':['materials','library'].includes(kind)}" :aria-label="names[kind]" :aria-busy="busy"><header class="between"><h2>{{names[kind]}}</h2><button class="btn sm ghost" aria-label="关闭面板" @click="dialog?.close()">✕</button></header><div class="future-panel-body"><div v-if="kind!=='delete'" class="banner info" role="status">{{service}}</div>
 <template v-if="['materials','library','local'].includes(kind)"><div class="between"><div class="tabs"><button class="tab" :class="{active:tab==='library'}" @click="tab='library'">知识库</button><button class="tab" :class="{active:tab==='selected'}" @click="tab='selected'">已选文件（0）</button></div><button class="btn sm" disabled>清空已选</button></div><div v-if="kind==='local'" class="future-upload-zone"><span>⇧</span><b>选择或拖拽会议背景材料</b><p>支持 PDF、Word、PPT、Excel、TXT 等文档</p><button class="btn" disabled>选择本地文件</button></div><div v-else-if="tab==='library'" class="material-picker"><aside><input v-model="query" class="input" placeholder="搜索知识库"/><div class="empty small">暂无可读取的知识库</div></aside><section><div class="between"><b>文件列表</b><input class="input" placeholder="搜索文件名称" disabled/></div><table class="tbl"><thead><tr><th><input type="checkbox" disabled aria-label="全选材料"/></th><th>文件名称</th><th>类型</th><th>版本</th><th>更新时间</th></tr></thead></table><div class="empty"><p>选择知识库后查看有权访问的文件</p><span class="small muted">材料服务接入后可选择真实文件及版本。</span></div></section></div><div v-else class="empty">尚未选择背景材料</div><p class="small muted mt12">已选文件跨知识库保留；添加材料不会改变源文件访问权限。</p></template>
 <template v-else-if="kind==='template'"><label class="form-label">模板名称 <span class="required">*</span><input v-model="title" class="input" placeholder="请输入模板名称" maxlength="80"/></label><div class="between mt16"><b>纪要章节（1–8项）</b><button class="btn sm" :disabled="sections.length>=8" @click="sections.push('')">＋ 添加章节</button></div><div v-for="(_,i) in sections" :key="i" class="template-section"><span>{{i+1}}</span><input v-model="sections[i]" class="input" placeholder="章节主题"/><button class="btn sm ghost" :disabled="sections.length===1" @click="sections.splice(i,1)">移除</button></div><p class="small muted">自定义模板仅本人可见。接入保存服务后可使用并重新生成纪要。</p></template>
 <template v-else-if="kind==='regenerate'"><p>仅重新生成“{{context}}”章节，其他章节的人工修改将保留。</p><label class="form-label mt16">生成要求<textarea class="input" rows="5" placeholder="补充关注重点、组织方式和表达要求"></textarea></label></template>
 <template v-else-if="kind==='speaker'"><div class="tabs"><button class="tab active">说话人信息</button><button class="tab" disabled>合并声道</button><button class="tab" disabled>拆分片段</button></div><label class="form-label">说话人姓名<input class="input" placeholder="填写姓名或选择通讯录人员" disabled/></label><label class="form-label mt16">机构 / 部门<input class="input" placeholder="未提供" disabled/></label><div class="empty">当前 TXT 未提供说话人或声道信息</div><button class="btn sm" disabled>撤销上次操作</button></template>
 <template v-else-if="kind==='correction'"><div class="tabs"><button class="tab active">纠错建议</button><button class="tab" disabled>更多候选</button></div><div class="empty">当前没有可用的纠错建议</div><label class="form-label">原始转写<div class="future-readonly">{{context||'请先接入纠错建议服务'}}</div></label><div class="flex mt16"><button class="btn" disabled>接受建议</button><button class="btn" disabled>拒绝建议</button><button class="btn" disabled>恢复原文</button><RouterLink to="/feedback" class="btn" @click="dialog?.close()">我的语料反馈</RouterLink></div></template>
 <template v-else-if="kind==='topic'||kind==='assign'"><label class="form-label">{{kind==='assign'?'选择专题':'专题名称'}} <span class="required">*</span><input v-if="kind==='topic'" v-model="title" class="input" placeholder="请输入专题名称"/><select v-else class="select" disabled><option>暂无可用专题</option></select></label><label v-if="kind==='topic'" class="form-label mt16">专题简介<textarea class="input" rows="4" placeholder="说明专题背景和会议归集范围"></textarea></label><p v-if="context" class="small muted mt12">{{context}}</p></template>
 <template v-else-if="kind==='delete'"><div v-if="error" class="banner error" role="alert">{{error}}</div><p>确认删除“{{context}}”？</p><p class="small muted mt12">删除后会议会从当前列表隐藏，历史记录保留且无法恢复。</p></template>
 <template v-else-if="kind==='recordInfo'"><label class="form-label">会议名称<input v-model="title" class="input" placeholder="请输入会议名称"/></label><label class="form-label mt16">会议日期<input class="input" type="date"/></label><label class="form-label mt16">会议摘要<textarea class="input" rows="4"></textarea></label><p class="small muted mt12">录音接入前，填写内容仅保留在当前面板。</p></template>
 </div><footer><span v-if="['materials','library'].includes(kind)" class="small muted">已选择 0 个文件</span><button class="btn" :disabled="busy" @click="dialog?.close()">取消</button><button class="btn primary" :disabled="kind!=='delete'||busy||!deleteMeetingId||!deleteRevisionToken" :title="kind==='delete'?undefined:service" @click="submit">{{kind==='template'?'保存并使用':kind==='regenerate'?'重新生成':kind==='delete'?'确认删除':['materials','library','local'].includes(kind)?'添加到会议':'保存'}}</button></footer></dialog></template>
<style scoped>.future-panel{margin:auto;width:min(640px,calc(100vw - 40px));max-height:90dvh;padding:0;overflow:auto;border:1px solid var(--border);border-radius:10px;color:var(--text);background:white}.future-wide{width:min(1040px,calc(100vw - 40px))}.future-panel::backdrop{background:#11184955}.future-panel>header{padding:18px 24px;border-bottom:1px solid var(--border)}.future-panel h2{font-size:17px}.future-panel-body{padding:20px 24px}.future-panel-body>.banner{margin-bottom:18px}.future-panel>footer{position:sticky;bottom:0;display:flex;justify-content:flex-end;align-items:center;gap:10px;padding:14px 24px;border-top:1px solid var(--border);background:white}.future-panel>footer>span{margin-right:auto}.future-panel .form-label>.input,.future-panel .form-label>.select{display:block;width:100%;margin-top:8px}.material-picker{display:grid;grid-template-columns:220px minmax(0,1fr);border:1px solid var(--border);border-radius:8px;min-height:340px;overflow:hidden}.material-picker>aside{border-right:1px solid var(--border);padding:16px}.material-picker .input{width:100%}.material-picker>section>.between{padding:16px;gap:16px}.material-picker .between>.input{max-width:220px}.template-section{display:flex;align-items:center;gap:10px;margin:12px 0}.template-section .input{flex:1;min-width:0}.future-upload-zone{text-align:center;padding:40px;border:1px dashed var(--border2);border-radius:8px}.future-upload-zone>*{display:block;margin:12px auto}.future-upload-zone>span{font-size:32px;color:var(--orange)}.future-readonly{margin-top:8px;padding:12px;border:1px solid var(--border);border-radius:6px}.required{color:var(--red)}.muted{color:var(--muted)}@media(max-width:700px){.material-picker{grid-template-columns:1fr}.material-picker>aside{border-right:0;border-bottom:1px solid var(--border)}}
</style>
